import numpy as np,heapq
from PIL import Image
im=np.asarray(Image.open('/app/target.png').convert('L'))<100;h,w=im.shape
m=im.copy()
while 1:
 changed=False
 for phase in (0,1):
  p=np.pad(m,1);n=p[:-2,1:-1];ne=p[:-2,2:];e=p[1:-1,2:];se=p[2:,2:];s=p[2:,1:-1];sw=p[2:,:-2];ww=p[1:-1,:-2];nw=p[:-2,:-2];ns=[n,ne,e,se,s,sw,ww,nw];B=sum(x.astype(np.uint8) for x in ns);A=sum((~x&y).astype(np.uint8) for x,y in zip(ns,ns[1:]+ns[:1]))
  if phase==0:c=m&(B>=2)&(B<=6)&(A==1)&~(n&e&s)&~(e&s&ww)
  else:c=m&(B>=2)&(B<=6)&(A==1)&~(n&e&ww)&~(n&s&ww)
  if c.any():m[c]=0;changed=True
 if not changed:break
ys,xs=np.where(m);nodes=list(zip(ys.tolist(),xs.tolist()));idx={pt:i for i,pt in enumerate(nodes)};N=len(nodes);adj=[[] for _ in nodes]
for i,(y,x) in enumerate(nodes):
 for dy in (-1,0,1):
  for dx in (-1,0,1):
   if dx==dy==0:continue
   j=idx.get((y+dy,x+dx))
   if j is not None:adj[i].append((j,1.41421356 if dx and dy else 1.0))
ends=[]
for i,(y,x) in enumerate(nodes):
 if len(adj[i])==1:ends.append((x,y,i))
print('ends',[(x,y) for x,y,_ in ends])
def near(x,y):return min(ends,key=lambda e:(e[0]-x)**2+(e[1]-y)**2)[2]
def path(a,b):
 s=near(*a);t=near(*b);dist=[1e12]*N;prev=[-1]*N;dist[s]=0;q=[(0,s)]
 while q:
  d,i=heapq.heappop(q)
  if d!=dist[i]:continue
  if i==t:break
  for j,c in adj[i]:
   nd=d+c
   if nd<dist[j]:dist[j]=nd;prev[j]=i;heapq.heappush(q,(nd,j))
 out=[];i=t
 while i!=-1:out.append(nodes[i]);i=prev[i]
 out=out[::-1]
 print(a,b,'=>',nodes[s][::-1],nodes[t][::-1],'len',len(out))
 return [(x,y) for y,x in out]
